from typing import List


class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        if n <= 3:
            return sum(map(sum, fruits))
        diagonal = sum(fruits[i][i] for i in range(n))

        def collect(grid):
            neg = float("-inf")
            dp = [neg] * n
            dp[n - 1] = grid[0][n - 1]
            for i in range(1, n - 1):
                new = [neg] * n
                for j in range(max(i + 1, n - 1 - i), n):
                    best = dp[j]
                    if j > 0 and dp[j - 1] > best:
                        best = dp[j - 1]
                    if j + 1 < n and dp[j + 1] > best:
                        best = dp[j + 1]
                    new[j] = best + grid[i][j]
                dp = new
            return dp[n - 1]

        transposed = [list(row) for row in zip(*fruits)]
        return diagonal + collect(fruits) + collect(transposed)
